// План specs/usage-tracking.md 1.1 (кейс .qa/tests/usage-tracking/UT-01). Владелец (admin), компания «test», десктоп, EN.
// @prod-safe: только просмотр. В конце selected-company-id возвращается на «test».
import { test, expect } from '../../fixtures';
import { COUNTERS, TEST_COMPANY, byPersonTotal, expectSelected, expectUsageScreen, openUsage, restoreTest, startInTest } from './usage-helpers';

test.describe('Usage tracking: Activity & usage screen (#04d347)', () => {
  test('Owner: Activity & usage shows This month, 7 numeric counters, Per day and By person with owner and Earlier records #04d347 @desktop @prod-safe', async ({ asUser }) => {
    const owner = await asUser('admin');
    await startInTest(owner);
    try {
      // Сервер отдаёт сводку (rpc usage_summary 200).
      expect(await openUsage(owner), 'usage_summary').toBe(200);
      await expectSelected(owner, TEST_COMPANY.name);

      const { values, people } = await expectUsageScreen(owner);

      // By person — разбивка тех же событий: сумма Events = сумма счётчиков
      // (на скриншотах 14.10/18.10: 123=92+31, 144=113+31, 173=142+31).
      const countersTotal = COUNTERS.reduce((s, c) => s + values[c], 0);
      expect(await byPersonTotal(people), 'сумма By person = сумма счётчиков').toBe(countersTotal);
    } finally {
      await restoreTest(owner);
    }
  });
});
